import {
  MapContainer,
  TileLayer,
  Polyline,
  Marker,
  useMap
} from "react-leaflet";
import { useEffect, useState } from "react";
import axios from "axios";
import L from "leaflet";

// 🔥 Fix marker icons
delete L.Icon.Default.prototype._getIconUrl;
L.Icon.Default.mergeOptions({
  iconRetinaUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon-2x.png",
  iconUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-icon.png",
  shadowUrl:
    "https://unpkg.com/leaflet@1.7.1/dist/images/marker-shadow.png",
});

// 🗺️ Fit map to full path
function FitBounds({ path }) {
  const map = useMap();

  useEffect(() => {
    if (path.length > 1) {
      map.fitBounds(path, { padding: [50, 50] });
    }
  }, [path, map]);

  return null;
}

function App() {
  const [fullPath, setFullPath] = useState([]);   // full telemetry
  const [path, setPath] = useState([]);           // animated path
  const [currentIndex, setCurrentIndex] = useState(0);
  const [latest, setLatest] = useState(null);
  const [isReplayDone, setIsReplayDone] = useState(false);

  useEffect(() => {
    fetchInitialData();
  }, []);

  // 🚀 Fetch initial path
  const fetchInitialData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/path");

      const coords = res.data.map(d => [
        d.location.coordinates[1],
        d.location.coordinates[0],
      ]);

      setFullPath(coords);

    } catch (err) {
      console.error(err);
    }
  };

  // 🎬 Animate path (REPLAY)
  useEffect(() => {
    if (fullPath.length === 0) return;

    const interval = setInterval(() => {
      setCurrentIndex(prev => {
        if (prev >= fullPath.length - 1) {
          clearInterval(interval);
          setIsReplayDone(true);
          return prev;
        }

        setPath(fullPath.slice(0, prev + 1));
        return prev + 1;
      });
    }, 200); // speed of animation

    return () => clearInterval(interval);
  }, [fullPath]);

  // 🚁 After replay → switch to live tracking
  useEffect(() => {
    if (!isReplayDone) return;

    const interval = setInterval(fetchLiveData, 3000);
    return () => clearInterval(interval);
  }, [isReplayDone]);

  const fetchLiveData = async () => {
    try {
      const res = await axios.get("http://localhost:3000/latest");

      if (res.data?.location) {
        const newPoint = [
          res.data.location.coordinates[1],
          res.data.location.coordinates[0],
        ];

        setPath(prev => [...prev, newPoint]);
        setLatest(res.data);
      }

    } catch (err) {
      console.error(err);
    }
  };

  return (
    <div style={{ height: "100vh" }}>
      <h2 style={{ padding: "10px" }}>🚁 Drone Replay + Live</h2>

      <MapContainer
        center={[12.9716, 77.5946]}
        zoom={18}
        style={{ height: "80vh", width: "100%" }}
      >
        <TileLayer
          url="https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png"
        />

        {/* 🔵 Animated Path */}
        <Polyline positions={path} color="blue" />

        {/* 📍 Moving Marker */}
        {path.length > 0 && (
          <Marker position={path[path.length - 1]} />
        )}

        {/* 🗺️ Fit once */}
        <FitBounds path={fullPath} />
      </MapContainer>
    </div>
  );
}

export default App;
